	private static int selectedRangeSize(int[] counts, int[] eventMapping) {
		int total = 0;
		for (int oldEventId = 1; oldEventId < eventMapping.length; oldEventId++) {
			if (eventMapping[oldEventId] != 0) {
				total = Math.addExact(total, counts[oldEventId]);
			}
		}
		return total;
	}

	private static void copySelectedRanges(int[] source, int[] starts, int[] counts, int[] eventMapping,
			int[] projectedStarts, int[] target) {
		int targetOffset = 0;
		for (int oldEventId = 1; oldEventId < eventMapping.length; oldEventId++) {
			int projectedEventId = eventMapping[oldEventId];
			if (projectedEventId == 0) {
				continue;
			}
			projectedStarts[projectedEventId] = targetOffset;
			int count = counts[oldEventId];
			System.arraycopy(source, starts[oldEventId], target, targetOffset, count);
			targetOffset += count;
		}
	}

